package ama.transcript;
import ama.contract.MinutesContracts.*;import ama.contract.IdentityContracts.Actor;import ama.contract.TaskContracts.SubjectRef;import ama.storage.FileRegistry;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Same-issuer graph persistence; inert copy rows never grant write authority. */
final class MinutesSavedWriter {
 private final JdbcTranscriptAuthority authority;private final JdbcTemplate j;
 MinutesSavedWriter(JdbcTranscriptAuthority authority){this.authority=authority;j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);}
 boolean firstSave(Object scope,FileRegistry.LockedMeeting gate,Actor actor,MinutesGraphCapture.Graph graph,MinutesExternalPreparation.Observation observation){
  authority.requireMinutesWrite(scope,gate,actor,graph);var root=graph.discovery().root();var guard=graph.auxiliary().getOrDefault("meeting_minutes_editor_guard",List.of());
  if(root.get("minutes_revision_id")!=null||guard.size()!=1||((Number)guard.getFirst().get("intent_epoch")).longValue()!=0)return false;
  var plan=observation.saved;require(plan!=null&&observation.plan!=null&&graph.discovery().pending()!=null,PROVENANCE_UNAVAILABLE);long before=((Number)root.get("revision")).longValue();require(before==observation.request.spec.businessVersion()&&before<Long.MAX_VALUE-1,PROVENANCE_UNAVAILABLE);
  // The candidate and saved copy consume separate slots in each already locked history.
  long body=next(graph,"minutes_revision",2),set=next(graph,"element_set",2);var rows=plan.rows(body,set);writeAndReadback(rows,plan,observation.request.input.budget());
  require(j.update("UPDATE generation_candidate SET state='ADOPTED',decided_at=UTC_TIMESTAMP(6) WHERE id=? AND task_id=? AND state='PENDING' AND base_revision=?",observation.plan.candidateId(),observation.request.taskId,before)==1,PROVENANCE_UNAVAILABLE);
  advance(scope,gate,actor,graph,plan,observation.request.spec.inputFingerprint(),before+1);
  new ama.audit.JdbcAuditAdapter(authority.dataSource()).append(new ama.contract.AuditContracts.AuditEvent(actor.enterpriseId(),"MINUTES_FIRST_SAVED",graph.discovery().meeting(),before+1,"SUCCEEDED",observation.token.executionId(),java.time.Instant.now()));
  new ama.task.JdbcOutbox(authority.dataSource(),new MinutesEventReferences(authority.dataSource()).validators()).append(new ama.contract.OutboxContracts.EventDraft("MINUTES_FIRST_SAVED",null,new SubjectRef("MEETING",graph.discovery().meeting()),before+1,new ama.contract.OutboxContracts.Reference("MINUTES_REVISION",plan.body())));return true;
 }
 void advance(Object scope,FileRegistry.LockedMeeting gate,Actor actor,MinutesGraphCapture.Graph graph,MinutesSavedGraphPlan plan,String fingerprint,long revision){
  authority.requireMinutesWrite(scope,gate,actor,graph);String meeting=graph.discovery().meeting();long old=((Number)graph.discovery().root().get("revision")).longValue();var fences=new ama.task.JdbcSubjectFences(authority.dataSource(),Set.of("MEETING"));var subject=fences.lock(new SubjectRef("MEETING",meeting),false).orElseThrow(()->fail(PROVENANCE_UNAVAILABLE));require(subject.businessVersion()==old&&revision==old+1,PROVENANCE_UNAVAILABLE);
  require(j.update("UPDATE meeting SET minutes_revision_id=?,element_set_id=?,revision=?,needs_generation=0,generation_fingerprint=?,final_confirmation_id=NULL,updated_at=UTC_TIMESTAMP(6) WHERE id=? AND revision=? AND cancel_epoch=? AND ever_published=0 AND stage<>'PUBLISHED' AND lifecycle='ACTIVE' AND governance_state='ACTIVE'",plan.body(),plan.set(),revision,fingerprint,meeting,old,subject.cancelEpoch())==1,PROVENANCE_UNAVAILABLE);
  require(j.update("UPDATE meeting_search_projection SET meeting_revision=? WHERE meeting_id=?",revision,meeting)==1,PROVENANCE_UNAVAILABLE);fences.advance(subject,revision,subject.cancelEpoch(),false);authority.finishMinutesGraphTransition(scope,gate,actor,graph,revision);
 }
 void writeAndReadback(List<FullRow> rows,MinutesSavedGraphPlan plan,TranscriptAcquisitionBudget.Ledger budget){for(var row:rows)insert(row);var reader=new SavedTranscriptRows(j,budget,authority.readBudget().maxManifestBytes());for(var row:rows){var keys=row.table().primaryKey();var actual=reader.rows(row.table(),String.join(" AND ",keys.stream().map(k->k+"=?").toList()),String.join(",",keys),1,true,keys.stream().map(row::string).toArray());require(actual.equals(List.of(row)),PROVENANCE_UNAVAILABLE);}require(j.queryForObject("SELECT COUNT(*) FROM result_review WHERE minutes_revision_id=? OR element_id IN (SELECT id FROM minutes_element WHERE set_id=?)",Long.class,plan.body(),plan.set())==0,PROVENANCE_UNAVAILABLE);}
 void validateFirstSave(MinutesExternalPreparation.Observation observation){var plan=observation.saved;require(plan!=null,PROVENANCE_UNAVAILABLE);var root=j.queryForMap("SELECT minutes_revision_id,element_set_id,revision,generation_fingerprint,needs_generation FROM meeting WHERE id=?",observation.request.spec.subject().id());require(plan.body().equals(root.get("minutes_revision_id"))&&plan.set().equals(root.get("element_set_id"))&&((Number)root.get("revision")).longValue()==observation.request.spec.businessVersion()+1&&((Number)root.get("needs_generation")).longValue()==0&&observation.request.spec.inputFingerprint().equals(root.get("generation_fingerprint")),PROVENANCE_UNAVAILABLE);}
 private void insert(FullRow row){var columns=row.table().columns();var args=new Object[columns.size()];for(int i=0;i<args.length;i++){var value=row.cells().get(i);args[i]=value instanceof NullCell?null:value instanceof UIntCell n?n.value():columns.get(i).kind()==CellKind.TIMESTAMP?java.time.LocalDateTime.ofInstant(java.time.Instant.parse(((TextCell)value).value()),java.time.ZoneOffset.UTC):((TextCell)value).value();}require(j.update("INSERT INTO "+row.table().sqlName()+"("+String.join(",",columns.stream().map(ColumnSpec::name).toList())+") VALUES ("+String.join(",",Collections.nCopies(args.length,"?"))+")",args)==1,PROVENANCE_UNAVAILABLE);}
 private static long next(MinutesGraphCapture.Graph graph,String name,int slots){var highest=graph.auxiliary().get(name+"_history_max");require(highest!=null&&highest.size()<=1,PROVENANCE_UNAVAILABLE);long old=highest.isEmpty()?0:((Number)highest.getFirst().get("revision")).longValue();require(old>=0&&old<=Long.MAX_VALUE-1-slots,BUDGET_EXCEEDED);return old+slots;}
}
